requires_restic = pytest.mark.skipif(
    shutil.which("restic") is None and not os.environ.get("BOXYARD_RESTIC"),
    reason="restic binary not available",
)

pytestmark = requires_restic


def run(coro):
    return asyncio.run(coro)


def tree(path: Path) -> dict[str, bytes]:
    """Content of a tree, for byte-identical comparisons."""
    return {
        str(p.relative_to(path)): p.read_bytes()
        for p in sorted(Path(path).rglob("*"))
        if p.is_file() and not p.is_symlink()
    }

