def test_a_missing_repo_is_reported_as_absent(tmp_path):
    absent = ResticRepo(
        url=str(tmp_path / "nothing-here"),
        password="p",
        cache_dir=tmp_path / "c",
    )
    assert run(repo_exists(absent)) is False


def test_a_wrong_password_does_not_read_as_absent(repo, tmp_path):
    """
    `repo_exists` must not conflate "no repo" with "cannot open it". Treating a
    wrong password as an empty repo would make a converted box look
    unconverted, and the next push would initialise a SECOND repo over the top.
    """
    wrong = ResticRepo(
        url=repo.url, password="not-the-password", cache_dir=tmp_path / "c2"
    )
    assert run(repo_exists(wrong)) is False  # cannot open
    # ...but the repo really is there, and opening it correctly proves it.
    assert run(repo_exists(repo)) is True


def test_the_ambient_environment_cannot_override_the_repo(repo, data, monkeypatch):
    """
    A `RESTIC_REPOSITORY` or `RESTIC_PASSWORD_FILE` inherited from the user's
    shell would silently redirect every operation. Under supervisor that is a
    box pushed into someone else's repository.
    """
    monkeypatch.setenv("RESTIC_REPOSITORY", "/somewhere/else")
    monkeypatch.setenv("RESTIC_PASSWORD_FILE", "/nonexistent")
    monkeypatch.setenv("RESTIC_PASSWORD_COMMAND", "false")
    result = run(push(repo, data))
    assert run(snapshot_exists(repo, result.snapshot_id)) is True

