def test_a_targeted_restore_takes_exactly_the_named_path(repo, data, tmp_path):
    (data / "package.json").write_text("root\n")
    (data / "sub" / "package.json").write_text("nested\n")
    (data / "sub" / "deeper").mkdir()
    (data / "sub" / "deeper" / "package.json").write_text("deepest\n")
    result = run(push(repo, data))

    dest = tmp_path / "targeted"
    dest.mkdir()
    run(
        run_restic(
            repo,
            [
                "restore",
                f"{result.snapshot_id}:{result.source_path}",
                "--target",
                str(dest),
            ]
            + anchored_include_args(["package.json"]),
        )
    )

    restored = sorted(str(p.relative_to(dest)) for p in dest.rglob("*") if p.is_file())
    assert restored == ["package.json"], (
        f"an unanchored --include would also restore the nested copies: {restored}"
    )
    assert (dest / "package.json").read_text() == "root\n"

