def test_unix_mode_survives_a_round_trip(repo, data, tmp_path):
    """
    This is why the exec-bit manifest is redundant for a restic-backed box.
    restic restores the LITERAL mode, which the manifest cannot express.
    """
    (data / "run.sh").write_text("#!/bin/sh\n")
    (data / "run.sh").chmod(0o755)
    (data / "notes.md").chmod(0o644)
    (data / "sub" / "tool.sh").write_text("#!/bin/sh\n")
    (data / "sub" / "tool.sh").chmod(0o775)

    result = run(push(repo, data))
    dest = tmp_path / "dest"
    run(pull(repo, dest, target_snapshot=result.snapshot_id, base_snapshot=None))

    assert (dest / "run.sh").stat().st_mode & 0o777 == 0o755
    assert (dest / "notes.md").stat().st_mode & 0o777 == 0o644
    assert (dest / "sub" / "tool.sh").stat().st_mode & 0o777 == 0o775

