def test_an_unchanged_box_is_not_reported_as_modified(repo, data):
    """
    A no-op backup reports `Dirs: 0 new, 1 changed` -- the root directory's own
    metadata. Counting that as modified makes every box permanently NEEDS_PUSH
    and silently disables the whole skip filter.
    """
    result = run(push(repo, data))
    assert run(local_is_modified(repo, data, result.snapshot_id)) is False


