def test_a_touched_manifest_alone_is_not_a_change(repo, data):
    """
    The manifest is excluded, so a box whose only difference is a regenerated
    `.boxyard-perms.json` must stay SYNCED -- otherwise every box with one
    pushes forever.
    """
    from boxyard import const

    result = run(push(repo, data))
    (data / const.BOX_PERMS_MANIFEST_REL_PATH).write_text('{"version":1,"x":[]}')
    assert run(local_is_modified(repo, data, result.snapshot_id)) is False

