def test_status_is_needs_pull_when_only_the_remote_moved(repo, data, tmp_path):
    """
    A REPLICA -- a machine whose checkout path differs from the pusher's, which
    on this fleet is every Mac/Linux pair. Its state record is what the caller
    supplies, exactly as `sync_box` will.
    """
    first = run(push(repo, data))
    dest = tmp_path / "dest"
    run(pull(repo, dest, target_snapshot=first.snapshot_id, base_snapshot=None))
    write_state(tmp_path / "yard", "box", first.snapshot_id)
    state = read_state(tmp_path / "yard", "box")

    (data / "notes.md").write_text("pushed elsewhere\n")
    second = run(push(repo, data, parent=first.snapshot_id))

    status = run(
        get_status(
            repo,
            dest,
            remote_snapshot=second.snapshot_id,
            local_snapshot=state["snapshot"],
            synced_at_unix=state["synced_at_unix"],
        )
    )
    assert status.condition is ResticCondition.NEEDS_PULL


def test_a_replica_at_a_different_path_is_not_falsely_modified(repo, data, tmp_path):
    """
    `backup --parent` matches BY PATH, so a parent taken elsewhere makes every
    file look new -- measured, identical content under a different path gives
    `files_new=1, files_unmodified=0`. Without the source-path check in
    `parent_is_usable` every cross-platform replica reports CONFLICT forever.
    """
    first = run(push(repo, data))
    dest = tmp_path / "dest"
    run(pull(repo, dest, target_snapshot=first.snapshot_id, base_snapshot=None))
    write_state(tmp_path / "yard", "box", first.snapshot_id)
    state = read_state(tmp_path / "yard", "box")

    assert tree(dest) == tree(data), "precondition: the replica is identical"
    assert (
        run(
            local_is_modified(
                repo,
                dest,
                first.snapshot_id,
                synced_at_unix=state["synced_at_unix"],
            )
        )
        is False
    )


def test_status_without_a_timestamp_is_conservative(repo, data, tmp_path):
    """
    A state record written before `synced_at_unix` existed. We cannot tell, and
    refusing is the safe direction -- it costs a person a decision, never data.
    """
    first = run(push(repo, data))
    dest = tmp_path / "dest"
    run(pull(repo, dest, target_snapshot=first.snapshot_id, base_snapshot=None))
    (data / "notes.md").write_text("pushed elsewhere\n")
    second = run(push(repo, data, parent=first.snapshot_id))

    status = run(
        get_status(
            repo,
            dest,
            remote_snapshot=second.snapshot_id,
            local_snapshot=first.snapshot_id,
        )
    )
    assert status.condition is ResticCondition.CONFLICT


def test_status_is_conflict_when_both_moved(repo, data, tmp_path):
    import time

    first = run(push(repo, data))
    dest = tmp_path / "dest"
    run(pull(repo, dest, target_snapshot=first.snapshot_id, base_snapshot=None))
    write_state(tmp_path / "yard", "box", first.snapshot_id)
    state = read_state(tmp_path / "yard", "box")

    (data / "notes.md").write_text("theirs\n")
    second = run(push(repo, data, parent=first.snapshot_id))
    time.sleep(0.01)
    (dest / "notes.md").write_text("mine\n")

    status = run(
        get_status(
            repo,
            dest,
            remote_snapshot=second.snapshot_id,
            local_snapshot=state["snapshot"],
            synced_at_unix=state["synced_at_unix"],
        )
    )
    assert status.condition is ResticCondition.CONFLICT
    assert (dest / "notes.md").read_text() == "mine\n"


