def test_a_forgotten_base_does_not_become_a_false_conflict(repo, data, tmp_path):
    """The whole point of `synced_at_unix`, end to end through `get_status`."""
    import time

    first = run(push(repo, data))
    dest = tmp_path / "dest"
    run(pull(repo, dest, target_snapshot=first.snapshot_id, base_snapshot=None))
    synced_at = time.time() + 1

    (data / "notes.md").write_text("theirs\n")
    second = run(push(repo, data, parent=first.snapshot_id))
    run(run_restic(repo, ["forget", first.snapshot_id]))

    status = run(
        get_status(
            repo,
            dest,
            remote_snapshot=second.snapshot_id,
            local_snapshot=first.snapshot_id,
            synced_at_unix=synced_at,
        )
    )
    assert status.condition is ResticCondition.NEEDS_PULL

